// n8n Function Node: Calculate next follow-up date and increment follow_up_count

const MAX_FOLLOW_UP = 4;
const followUpDelays = [1, 2, 2, 3]; // delays in working days for follow_up_count 0-3

function getNextFollowUpDate(lastCallDate, followUpCount) {
    if (followUpCount >= MAX_FOLLOW_UP) return null;

    let daysToAdd = followUpDelays[followUpCount];
    let nextDate = new Date(lastCallDate);

    while (daysToAdd > 0) {
        nextDate.setDate(nextDate.getDate() + 1);
        const day = nextDate.getDay();
        if (day !== 0 && day !== 6) { // skip Sunday(0) and Saturday(6)
            daysToAdd--;
        }
    }
    return nextDate.toISOString().split('T')[0]; // YYYY-MM-DD
}

// Safely extract call data
const callData = $json.call || {};
const dynamicVars = callData.retell_llm_dynamic_variables || {};

// Current follow-up count
let followUpCount =  $('Get Request').first().json.follow_up_count|| 0;

// Increment follow-up count, but cap at MAX_FOLLOW_UP
const updatedFollowUpCount = Math.min(followUpCount + 1, MAX_FOLLOW_UP);

// Determine last call date
const lastCallTimestamp = callData.end_timestamp ? new Date(callData.end_timestamp) : new Date();

// Calculate next follow-up date
const nextFollowUp = getNextFollowUpDate(lastCallTimestamp, followUpCount);

return [
    {
        json: {
            last_call_date: lastCallTimestamp.toISOString().split('T')[0],
            next_follow_up_date: nextFollowUp
        }
    }
];

const items = $input.all();

return items.map(item => {
  const data = item.json;

  const start = $('Webhook').first().json.body.call.start_timestamp;
  const end = $('Webhook').first().json.body.call.end_timestamp;

  const startISO = start ? new Date(start).toISOString() : null;
  const endISO = end ? new Date(end).toISOString() : null;

  return {
    json: {
      ...data,
      start_time_iso: startISO,
      end_time_iso: endISO
    }
  };
});

const webhookData = $('Webhook').first().json;
const call = webhookData.body?.call || {};
const dv = call.retell_llm_dynamic_variables || {};
const metadata = call.metadata || {};
const analysis = call.call_analysis || {};
const customData = analysis.custom_analysis_data || {};

const cleanNull = (val) =>
  (val === 'Null' || val === 'null' || val === '' || val === undefined) ? null : val;

const idsRaw = dv.request_ids || metadata.request_ids || '';

const startISO = call.start_timestamp ? new Date(call.start_timestamp).toISOString() : null;
const endISO = call.end_timestamp ? new Date(call.end_timestamp).toISOString() : null;
const startReadable = call.start_timestamp ? new Date(call.start_timestamp).toLocaleString('en-US', { timeZone: 'America/New_York' }) : null;
const endReadable = call.end_timestamp ? new Date(call.end_timestamp).toLocaleString('en-US', { timeZone: 'America/New_York' }) : null;

const noAnswerReasons = ['dial_no_answer', 'voicemail', 'no_answer','invalid_destination','inactivity'];
const status = customData.status ||
  (noAnswerReasons.includes(call.disconnection_reason) ? 'follow-up' : 'attempted');

const disposition = customData.disposition || call.disconnection_reason || null;

return [{
  json: {
    // ───── Core IDs ─────
    call_id:                    call.call_id,
    retell_call_id:             call.call_id,
    agent_id:                   call.agent_id,
    agent_name:                 call.agent_name,
    agent_version:              call.agent_version,

    // ───── Request Info ─────
    request_id:                 idsRaw,
    request_count:              dv.request_count          || metadata.request_count          || null,
    recipient_name:             dv.recipient_name         || metadata.recipient_name         || null,
    requestor_email:            cleanNull(dv.requestor_email || metadata.requestor_email)    || null,
    requestor_organization:     dv.requestor_organization || metadata.requestor_organization  || null,
    invoice_amount:             dv.invoice_amount         || metadata.invoice_amount         || null,
    total_invoice_amount:       dv.total_invoice_amount   || metadata.total_invoice_amount   || null,
    days_past_due:              dv.days_past_due          || metadata.days_past_due          || null,
    patient_name:               dv.patient_name           || metadata.patient_name           || null,

    // ───── Call Outcome ─────
    disposition:                disposition,
    status:                     status,
    outcome:                    disposition,
    last_call_outcome:          cleanNull(analysis.call_summary) || call.disconnection_reason || null,
    call_status:                call.call_status,
    disconnection_reason:       call.disconnection_reason,
    call_successful:            analysis.call_successful,
    in_voicemail:               analysis.in_voicemail,
    user_sentiment:             analysis.user_sentiment,
    call_type:                  call.call_type,
    direction:                  call.direction,

    // ───── Timestamps ─────
    timestamp:                  endISO,
    call_started_at:            startISO,
    call_completed_at:          endISO,
    call_started_at_readable:   startReadable,
    call_completed_at_readable: endReadable,
    duration_ms:                call.duration_ms,
    event_timestamp:            webhookData.body?.event_timestamp || null,

    // ───── Phone Numbers ─────
    to_number:                  call.to_number,
    from_number:                call.from_number,

    // ───── Payment Info ─────
    payment_method:             cleanNull(customData.payment_method),
    promised_amount:            cleanNull(customData.promised_amount),
    promised_date:              cleanNull(customData.promised_date),
    follow_up_count:            Number(customData.follow_up_count) || 0,
    follow_up_required_flag:    customData.follow_up_required_flag ?? null,
    next_follow_up_date:        cleanNull(customData.next_follow_up_date),

    // ───── Recording ─────
    recording_url:              call.recording_url || null,
    twilio_call_sid:            call.telephony_identifier?.twilio_call_sid || null,
  }
}];

const body = $('Webhook').first().json.body || {};
const call = body.call || {};
const analysis = call.call_analysis || {};
const customData = analysis.custom_analysis_data || {};
const dv = call.retell_llm_dynamic_variables || {};
const metadata = call.metadata || {};

const cleanNull = (val) =>
  (!val || val === 'Null' || val === 'null' || val === '') ? null : val;

const cleanAmount = (val) => {
  if (!val || val === 'Null' || val === '') return null;
  const cleaned = parseFloat(String(val).replace(/[$,]/g, ''));
  return isNaN(cleaned) ? null : cleaned;
};

return [{
  json: {
    agent_type:     "b2b_collections",
    call_timestamp: body.event_timestamp || null,
    disposition:    cleanNull(customData.disposition) || call.disconnection_reason || null,
    notes:          cleanNull(analysis.call_summary),
    metadata: {
      payment_method:  cleanNull(customData.payment_method),
      promised_date:   cleanNull(customData.promised_date),
      promised_amount: cleanAmount(customData.promised_amount),
      customer_name:   cleanNull(customData.recipent_name) ||
                       cleanNull(dv.recipient_name)        ||
                       cleanNull(metadata.recipient_name)  || null,
    }
  }
}];

// n8n Function Node: Calculate next follow-up date and increment follow_up_count

const MAX_FOLLOW_UP = 4;

// Delays in working days for follow_up_count 0-3
// First 2 follow-ups = same day
const followUpDelays = [0, 0, 2, 3];

function getNextFollowUpDate(lastCallDate, followUpCount) {
    if (followUpCount >= MAX_FOLLOW_UP) return null;

    let daysToAdd = followUpDelays[followUpCount];
    let nextDate = new Date(lastCallDate);

    while (daysToAdd > 0) {
        nextDate.setDate(nextDate.getDate() + 1);

        const day = nextDate.getDay();

        // Skip Saturday (6) and Sunday (0)
        if (day !== 0 && day !== 6) {
            daysToAdd--;
        }
    }

    return nextDate.toISOString().split('T')[0]; // YYYY-MM-DD
}

// Safely extract call data
const callData = $json.call || {};
const dynamicVars = callData.retell_llm_dynamic_variables || {};

// Current follow-up count
let followUpCount = $('Get Request').first().json.follow_up_count || 0;

// Increment follow-up count, but cap at MAX_FOLLOW_UP
const updatedFollowUpCount = Math.min(
    followUpCount + 1,
    MAX_FOLLOW_UP
);

// Determine last call date
const lastCallTimestamp = callData.end_timestamp
    ? new Date(callData.end_timestamp)
    : new Date();

// Calculate next follow-up date
const nextFollowUp = getNextFollowUpDate(
    lastCallTimestamp,
    followUpCount
);

return [
    {
        json: {
            last_call_date: lastCallTimestamp.toISOString().split('T')[0],
            next_follow_up_date: nextFollowUp,
            follow_up_count: updatedFollowUpCount
        }
    }
];
